import { Dimensions, StyleSheet } from 'react-native';

const { width } = Dimensions.get('window');

export const styles = StyleSheet.create({
  // 弹窗容器
  modalContainer: {
    flex: 1,
    backgroundColor: '#fff',
  },
  // 弹窗头部
  modalHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
  },
  cancelText: {
    fontSize: 16,
    color: '#007AFF',
  },
  modalTitle: {
    fontSize: 18,
    fontWeight: '500',
  },

  // --- 日历头部样式 ---
  calendarHeaderWrapper: {
    marginBottom: 8,
  },
  // 月份行（包含左右箭头）
  monthRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    marginBottom: 8,
  },
  arrowBtn: {
    width: 32,
    height: 32,
    justifyContent: 'center',
    alignItems: 'center',
  },
  arrowText: {
    fontSize: 20,
    color: '#007AFF',
  },
  calendarMonthTitle: {
    marginLeft:60,
    marginRight:60,
    fontSize: 16,
    fontWeight: '500',
    color: '#333',
  },
  // 星期行（对齐到日期列）
  weekDaysContainer: {
    flexDirection: 'row',
    paddingHorizontal: 16,
  },
  weekDayText: {
    marginLeft: 0,
    marginRight: 0,
    position:'relative',
    // flex: 1,
    textAlign: 'center',
    fontSize: 14,
    color: '#666',
  },

  // --- 日期单元格样式 ---
  calendarDayText: {
    textAlign: 'center',
    fontSize: 16,
    color: '#333',
    paddingVertical: 8,
  },
  disabledDayText: {
    color: '#ccc',
  },
  selectedDayText: {
    color: 'white',
    fontWeight: 'bold',
  },
  todayDayText: {
    fontWeight: 'bold',
    color: '#007AFF',
  },
});
